# Let me search more thoroughly in the JSON data for any price index data
import json

with open('/app/resources/treasury_bulletin_1980_05.json') as f:
    data = json.load(f)

# Find any numeric data that could be related to CPI or price indexes
def find_numbers(obj, path='', depth=0):
    if depth > 5:
        return
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'index' in k.lower() or 'price' in k.lower() or 'cpi' in k.lower():
                print(f'{path}.{k}: {v}')
            find_numbers(v, f'{path}.{k}', depth+1)
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            find_numbers(v, f'{path}[{i}]', depth+1)

find_numbers(data)
